import{_ as t,o as s,c as r,a2 as o}from"./chunks/framework.B_GyVC5q.js";const g=JSON.parse('{"title":"Notes de version","description":"","frontmatter":{"title":"Notes de version"},"headers":[],"relativePath":"release-notes/fr.md","filePath":"release-notes/fr.md"}'),n={name:"release-notes/fr.md"};function a(i,e,l,d,u,c){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="notes-de-version" tabindex="-1">Notes de version <a class="header-anchor" href="#notes-de-version" aria-label="Permalink to &quot;Notes de version&quot;">​</a></h1><hr><h2 id="_1-5-x" tabindex="-1">1.5.x <a class="header-anchor" href="#_1-5-x" aria-label="Permalink to &quot;1.5.x&quot;">​</a></h2><h3 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h3><p>La version <code>1.5.x</code> ajoute les <strong>Flux</strong> (canevas visuel pour des pipelines de données/requêtes avec exécution/debug, modèles, bibliothèque, import/export et IA Flows) ; <strong>zip</strong> sur Générer / <strong>Répéter chacun</strong> pour des seeds parent–enfant rapides ; logos et portraits SVG locaux ; une IA Flows qui <strong>construit et optimise</strong> les graphes ; ajoute les <strong>actions et tâches IA</strong> (Générer des données / Interroger la dataclass avec historique en pied de page) ; ajoute <strong>Relations</strong> (canevas orbit pour les liens N:1, centrer, délier, historique et duplication avec sélection) ; ajoute le <strong>plan et chemin de requête</strong>, <strong>Copier au format</strong>, <strong>Copier la session</strong> sur desktop, le <strong>zoom d&#39;image</strong>, l&#39;hébergement <strong>Docker</strong>, le <strong>playground de templates</strong> d&#39;environnement et des évolutions des formulaires d&#39;entité (champs booléens, champ d&#39;upload, vider avant insertion) ; et peaufine les limites/aperçu d&#39;anonymisation, les compteurs/rechargement du catalogue, le statut en ligne, la gestion des clés de relation, le clavier mobile, les filtres de journal console, les journaux de flux verbeux (y compris tout réduire), les toasts compacts et l&#39;ouverture des liens desktop.</p><h3 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h3><h4 id="flux" tabindex="-1">Flux <a class="header-anchor" href="#flux" aria-label="Permalink to &quot;Flux&quot;">​</a></h4><ul><li><strong>Espace de travail Flux</strong> — Ouvrez depuis le contrôle <strong>Flux</strong> du pied de page, la palette de commandes (<strong>Flux</strong>), ou l&#39;écran d&#39;accueil. Construisez des pipelines sur un canevas avec ancres Début/Fin, une palette de blocs, un plan et un inspecteur.</li><li><strong>Bibliothèque</strong> — Enregistrez des flux par base ; recherchez, dupliquez, supprimez, tout effacer ; import / export / copier le JSON.</li><li><strong>Modèles</strong> — Partez du Tour des opérateurs, Evaluate et logique, Interroger des données, HTTP · Ping <code>$info</code>, ou Fichiers de confiance.</li><li><strong>Blocs données et réseau</strong> — Lister (multi-dataclass), Créer, Générer, Mettre à jour, Purger (requête / ensemble d&#39;entités / dataclass entière), Import CSV, HTTP, et Méthode (catalogue / singleton / dataclass / entité).</li><li><strong>Blocs d&#39;entrée</strong> — Injecter une charge (y compris les nombres <code>$faker</code>), ticks d&#39;Intervalle (<code>{ counter, timestamp }</code>) et Horodatage — sources qui émettent au démarrage (sans fil d&#39;entrée).</li><li><strong>Code et logique</strong> — Affecter des variables, Évaluer (TypeScript sandboxé <code>main()</code>), Si / Pour / <strong>Répéter chacun</strong> / Délai, Journal, Chronologie, Note (Markdown, ignorée à l&#39;exécution), et blocs d&#39;invite IA.</li><li><strong>Opérateurs de flux</strong> — Map, Filter, Take, Merge, ForkJoin, Buffer, Debounce et opérateurs liés style RxJS pour composer les pipelines. Les infobulles de la palette et du canevas renvoient vers la documentation RxJS officielle pour les opérateurs nommés.</li><li><strong>Exécution et debug</strong> — Exécuter, pause/reprendre, arrêter, pas à pas ; points d&#39;arrêt par bloc avec activation/désactivation globale ; suivre l&#39;étape en cours sur le canevas ; journal d&#39;exécution, watches, et console d&#39;évaluation au point d&#39;arrêt.</li><li><strong>Journal d&#39;exécution verbeux</strong> — Option <strong>Verbeux</strong> à côté du dry run. Chaque bloc journalise pending puis done (ou erreur) avec durée, entrées et sorties dépliables (même arbre d&#39;objets que la Console). Durée et copie restent à côté du texte. <strong>Tout réduire</strong> (barre d&#39;outils, menu overflow ou menu contextuel du journal) replie les lignes et arbres développés sans effacer le journal.</li><li><strong>Blocs Note</strong> — Les notes Markdown sont de la documentation uniquement : elles sont ignorées à l&#39;exécution et ne peuvent ni être désactivées ni recevoir un point d&#39;arrêt.</li><li><strong>Exécuter sur le serveur</strong> — Lorsque la base expose <code>FlowRunner</code> et que le flux n&#39;a pas de nœuds client uniquement ; les flux avec dossiers de confiance restent limités au desktop ou au mobile.</li><li><strong>IA Flows</strong> — Chat ancré pour <strong>créer des flux rapides</strong> à partir d&#39;une invite et <strong>refactoriser</strong> le graphe (generate par lots, zip des FK, repeatEach). Suggestions dont <strong>Optimiser la vitesse</strong>. Configurez un LLM dans Réglages.</li><li><strong>Zip sur Générer</strong> — FK séquentielles : la ligne <code>i</code> copie <code>entities[i]</code> d&#39;un generate précédent (chemin <code>from</code> tel que <code>nodes.addr.stdout.entities</code>, <code>attr</code> par défaut <code>ID</code>). Le nombre suit la liste parente. Préférez ceci à <code>$pick</code> quand chaque parent doit avoir un nombre garanti d&#39;enfants.</li><li><strong>Répéter chacun</strong> — Bloc logique qui répète chaque entité entrante N fois (valeur ou <code>{{$faker.number.int | between:10,50}}</code> par parent). À coupler avec le zip pour « 10–50 employés par société » sans boucle Pour + Créer.</li><li><strong>Faker par ligne sur Générer</strong> — Les modèles <code>$faker</code> / <code>$pick</code> restent non résolus jusqu&#39;à la création de chaque entité, donc noms, adresses et médias varient dans le lot (createMany).</li><li><strong>Logos et portraits SVG locaux</strong> — <code>{{$faker.company.logo}}</code> et <code>{{$faker.image.personPortrait}}</code> produisent des data URI SVG compactes (<code>female</code> / <code>male</code> optionnels). Pas d&#39;appel CDN avant <code>$upload</code>.</li><li><strong>CSV et relations</strong> — Imports CSV style dataInit avec colonnes de relation <code>$rel_*</code>, vagues ordonnées par dépendances, et option ignorer-si-non-vide.</li><li><strong>Champs IA alignés sur le catalogue</strong> — Remappez les clés de champs IA sur les attributs réels du catalogue ; renseignez les clés étrangères d&#39;entités liées depuis <code>{{item.__KEY}}</code> lors de la génération de lignes liées.</li></ul><h4 id="actions-et-taches-ia" tabindex="-1">Actions et tâches IA <a class="header-anchor" href="#actions-et-taches-ia" aria-label="Permalink to &quot;Actions et tâches IA&quot;">​</a></h4><ul><li><strong>Menu d&#39;actions IA</strong> — Sur les listes de dataclass, les lignes de barre latérale et le graphe de structure : <strong>Générer des données</strong>, <strong>Interroger la dataclass</strong>, et générer filtre/params (LLM requis).</li><li><strong>Tâches IA</strong> — Historique en pied de page pour les exécutions en arrière-plan ; annuler une tâche ou toutes ; dialogues de confirmation pour les étapes destructives ; inspection de l&#39;activité/trace.</li></ul><h4 id="requetes" tabindex="-1">Requêtes <a class="header-anchor" href="#requetes" aria-label="Permalink to &quot;Requêtes&quot;">​</a></h4><ul><li><strong>Plan et chemin de requête</strong> — Activez <code>$queryplan</code> / <code>$querypath</code> dans le Query Builder, le Client HTTP et l&#39;Exécuteur de méthodes ; inspectez l&#39;accès index vs séquentiel, les jointures, les timings et le JSON.</li><li><strong>Copier au format</strong> — Copiez la requête courante ou une entrée réseau de la console en code exécutable (<code>HTTPRequest</code> 4D, cURL, JavaScript, Python et d&#39;autres cibles).</li></ul><h4 id="desktop-et-hebergement" tabindex="-1">Desktop et hébergement <a class="header-anchor" href="#desktop-et-hebergement" aria-label="Permalink to &quot;Desktop et hébergement&quot;">​</a></h4><ul><li><strong>Copier la session</strong> — Connectez-vous via le navigateur depuis l&#39;écran de connexion ; confirmez pour envoyer les cookies de session dans l&#39;app desktop (installez la classe téléchargeable <code>CopySession</code>).</li><li><strong>Docker</strong> — Exécutez l&#39;image publiée ou construisez depuis <code>DataExplorer.zip</code> avec <code>BACKEND_URL</code> (voir Getting started).</li><li><strong>Zoom desktop</strong> — Menu Affichage Agrandir / Réduire / Taille réelle.</li></ul><h4 id="environnements-et-templates" tabindex="-1">Environnements et templates <a class="header-anchor" href="#environnements-et-templates" aria-label="Permalink to &quot;Environnements et templates&quot;">​</a></h4><ul><li><strong>Playground de templates</strong> — Sélecteur d&#39;environnement → <strong>Tester…</strong> pour évaluer templates, <code>$faker</code>, filtres et <code>$this</code> avec des exemples.</li><li><strong>Filtres pipe</strong> — Transformations supplémentaires dont <code>capitalize</code>, <code>title</code>, variantes trim, <code>take_before</code> / <code>take_after</code>, <code>remove</code> / <code>replace</code>, padding et <code>default</code>.</li></ul><h4 id="formulaires-d-entite-et-medias" tabindex="-1">Formulaires d&#39;entité et médias <a class="header-anchor" href="#formulaires-d-entite-et-medias" aria-label="Permalink to &quot;Formulaires d&#39;entité et médias&quot;">​</a></h4><ul><li><strong>Champs booléens</strong> — Case à cocher et édition bool-ou-template pour les attributs booléens.</li><li><strong>Champ d&#39;upload</strong> — Champs image/blob avec sélection de fichier, glisser-déposer, templates de dossiers de confiance, et réinitialisation de l&#39;état d&#39;upload.</li><li><strong>Vider avant insertion</strong> — Optionnellement supprimer toutes les entités de la dataclass avant une création par lot (avec confirmation).</li><li><strong>Concurrence d&#39;upload média</strong> — Matérialisation média parallèle et mise en cache pour la création multi-entités, l&#39;anonymisation et les flux.</li><li><strong>Traiter la clé de relation 0 comme vide</strong> — Option Réglages pour que les relations différées de clé <code>0</code> s&#39;affichent vides au lieu d&#39;être chargées.</li></ul><h4 id="relations" tabindex="-1">Relations <a class="header-anchor" href="#relations" aria-label="Permalink to &quot;Relations&quot;">​</a></h4><ul><li><strong>Canevas Relations</strong> — Explorez les liens many-to-one d’un enregistrement sur un graphe en orbite (centre + anneau). Ouvrez depuis la palette de commandes (<strong>Relations</strong>), le menu <strong>⋯</strong> des cartes ou du tableau, la vue entité, ou les cellules d’entité du terminal.</li><li><strong>Sélection vs Centrer</strong> — Cliquez un enregistrement lié pour l’inspecter dans le panneau de détails sans recentrer ; <strong>Centrer</strong> développe son voisinage N:1 et recentre le canevas.</li><li><strong>Rayons et délier</strong> — Cliquez un rayon de relation pour les détails du lien ; <strong>Délier</strong> efface la clé étrangère (avec confirmation) sans supprimer l’enregistrement lié.</li><li><strong>Historique et zoom</strong> — Historique de sélection avant/arrière ; zoom avant, arrière et ajuster (barre d’outils, molette, ou ⌘/Ctrl +/− / 0 lorsque le canevas a le focus).</li><li><strong>Dupliquer</strong> — Confirmation avant de dupliquer un enregistrement sur le canevas ; le toast de succès propose <strong>Sélectionner</strong> pour centrer le nouvel enregistrement.</li><li><strong>Actions de ligne</strong> — Les actions de liste et de carte d’entité passent par un menu <strong>⋯</strong> unique (Relations, copier JSON, dupliquer, supprimer).</li></ul><h4 id="outils-de-selection-et-ux-medias" tabindex="-1">Outils de sélection et UX médias <a class="header-anchor" href="#outils-de-selection-et-ux-medias" aria-label="Permalink to &quot;Outils de sélection et UX médias&quot;">​</a></h4><ul><li><strong>Limite et aperçu d&#39;anonymisation</strong> — Plafonnez le nombre d&#39;entités à anonymiser ; voyez limite vs ensemble d&#39;entités vs totaux dataclass ; aperçu plus riche avant l&#39;exécution.</li><li><strong>Zoom d&#39;image</strong> — Ouvrez les images dans un aperçu zoomable et déplaçable (+ / − / 0, molette, glisser).</li></ul><h4 id="catalogue-et-connectivite" tabindex="-1">Catalogue et connectivité <a class="header-anchor" href="#catalogue-et-connectivite" aria-label="Permalink to &quot;Catalogue et connectivité&quot;">​</a></h4><ul><li><strong>Compteurs de dataclass</strong> — Chargez les effectifs d&#39;entités à la demande (automatique si le catalogue est petit) pour les totaux et graphiques d&#39;accueil.</li><li><strong>Recharger le catalogue</strong> — Videz le cache et rechargez depuis les états vides / erreur.</li><li><strong>Statut en ligne</strong> — Indicateur hors ligne en pied de page ; l&#39;IA cloud et les mises à jour se mettent en pause, tandis que le REST LAN et les LLM locaux restent disponibles.</li><li><strong>Filtre de journal console</strong> — Niveaux multi-sélection (log, info, warn, error, réseau) avec un contrôle tri-état <strong>Tous les journaux</strong>.</li><li><strong>Rétention des journaux</strong> — Limite des logs de flux et limite de la console : <code>0</code> conserve toutes les entrées jusqu’à ce que vous vidiez le journal.</li><li><strong>Supprimer une entrée console</strong> — Supprimez des lignes individuelles du journal console ou réseau.</li><li><strong>Réinitialiser la sélection</strong> — Lancer une nouvelle requête efface la multi-sélection précédente pour que les résultats restent synchronisés.</li><li><strong>Toasts compacts</strong> — Les notifications de succès et d’erreur sont plus denses, avec des actions en ligne à côté du titre si besoin.</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Pages guide <a href="https://midrissi.github.io/4d-dataexplorer/guide/flows.html" target="_blank" rel="noreferrer">Flux</a> (zip Générer, Répéter chacun, journal verbeux, tout réduire, Notes, docs RxJS), <a href="https://midrissi.github.io/4d-dataexplorer/guide/console.html" target="_blank" rel="noreferrer">Console</a> (filtre de niveau), <a href="https://midrissi.github.io/4d-dataexplorer/guide/trusted-folders.html" target="_blank" rel="noreferrer">Dossiers de confiance</a> (grille d&#39;icônes), <a href="https://midrissi.github.io/4d-dataexplorer/guide/ai-actions.html" target="_blank" rel="noreferrer">Actions et tâches IA</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/getting-started.html#run-with-docker" target="_blank" rel="noreferrer">Docker</a>, plan de requête (Query Builder / Client HTTP / Exécuteur de méthodes), Copier au format, et Copier la session (desktop macOS).</li></ul><h3 id="corrections" tabindex="-1">Corrections <a class="header-anchor" href="#corrections" aria-label="Permalink to &quot;Corrections&quot;">​</a></h3><ul><li><strong>Unicité Generate</strong> — Generate n&#39;applique plus une seule valeur faker résolue à toutes les lignes clonées.</li><li><strong>Portraits</strong> — <code>$faker.image.personPortrait</code> ne dépend plus d&#39;une URL d&#39;image distante.</li><li><strong>Clavier virtuel mobile</strong> — Les éditeurs restent au-dessus du clavier à l&#39;écran pour que les champs restent visibles pendant la saisie.</li><li><strong>Console et nombreuses images</strong> — Les miniatures des dossiers de confiance n&#39;inondent plus la console ; la vue icônes reste virtualisée pour que les grands dossiers ne figent pas l&#39;UI.</li><li><strong>Chevauchement de la grille d&#39;icônes</strong> — Les tuiles gardent une hauteur de vignette fixe, coupent les noms sans casser l&#39;extension, et affichent le type en badge atténué sous le nom (pas sur l&#39;image).</li><li><strong>Zoom de page desktop</strong> — ⌘/Ctrl + inertie du trackpad ne zoome plus après relâchement du modificateur ; le zoom ne s&#39;applique que si le geste a commencé avec ⌘ ou Ctrl.</li><li><strong>Liens externes desktop</strong> — Les liens <code>https</code> / <code>http</code> / <code>mailto</code> (y compris la doc RxJS des infobulles d&#39;opérateurs) s&#39;ouvrent une seule fois dans le navigateur système. Recompilez l&#39;app desktop pour que les permissions d&#39;ouverture s&#39;appliquent.</li></ul><h2 id="_1-4-x" tabindex="-1">1.4.x <a class="header-anchor" href="#_1-4-x" aria-label="Permalink to &quot;1.4.x&quot;">​</a></h2><h3 id="apercu-1" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu-1" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h3><p>La version <code>1.4.x</code> ajoute les <strong>variables d&#39;environnement</strong> (couches globales, profil et base avec <code>{{templates}}</code>, filtres pipe et dynamiques Faker) ; ajoute les <strong>dossiers de confiance</strong> sur desktop et mobile (templates <code>{{$files.alias}}</code> pour <code>$upload</code>) ; ajoute le <strong>terminal ORDA</strong> (modes REPL et Code avec fichiers snippets) dans un dock bas partagé avec la Console ; ajoute <strong>l’export REST</strong> (collection v2.1 et OpenAPI 3.1 depuis le catalogue, le Client HTTP et l’Exécuteur de méthodes) ; ajoute les <strong>outils de sélection</strong> (analyse <code>$distinct</code> / <code>$compute</code>, export/import multi-formats, anonymisation Faker avec téléchargement, import comme nouveaux ou mise à jour in-place) ; ajoute les <strong>favoris</strong> pour le Client HTTP et l’Exécuteur de méthodes ; publie les applications <strong>iOS et Android</strong> ; améliore l’Exécuteur de méthodes (params/en-têtes Advanced, <code>$method=entityset</code> par défaut, erreurs dans le panneau résultat, états vides, raccourcis mod-clic) ; améliore le journal réseau de la console (corps pendant le pending, ouverture pendant le pending, annulation) ; et peaufine l&#39;expérience mobile (Client HTTP et dock).</p><h3 id="fonctionnalites-1" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites-1" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h3><h4 id="variables-d-environnement" tabindex="-1">Variables d&#39;environnement <a class="header-anchor" href="#variables-d-environnement" aria-label="Permalink to &quot;Variables d&#39;environnement&quot;">​</a></h4><ul><li><strong>Éditeur d&#39;environnements</strong> — Gérez les portées <strong>Globals</strong>, <strong>Profil</strong> et <strong>Cette base</strong> depuis Outils, la palette de commandes (<strong>Environnements</strong>), ou le sélecteur <strong>Environment</strong> du pied de page → <strong>Gérer…</strong>.</li><li><strong>Environnements actifs</strong> — Un environnement profil et un environnement base actifs à la fois ; le sélecteur du pied de page les choisit et prévisualise la liste fusionnée (les secrets restent masqués jusqu&#39;à révélation).</li><li><strong>Templates</strong> — Insérez <code>{{name}}</code> dans le Client HTTP, l&#39;Exécuteur de méthodes, le Query Builder, Créer une entité, les snippets du terminal ORDA et d&#39;autres champs templated ; résolution à l&#39;envoi / l&#39;exécution.</li><li><strong>Filtres pipe</strong> — Transformations style Liquid (<code>upper</code>, <code>lower</code>, <code>replace</code>, <code>unwrap</code>, <code>substring</code>, <code>hash:md5</code>, …) et options de génération (<code>female</code> / <code>male</code>, <code>min</code> / <code>max</code> / <code>between</code>, <code>after</code> / <code>before</code>).</li><li><strong>Contexte <code>$this</code></strong> — Accès à l’objet d’exécution (<code>{{$this.firstName}}</code>, <code>{{$this.headers.Authorization}}</code>, <code>{{$this.methodName}}</code>, …) pour les formulaires d’entité, le Client HTTP, l’Exécuteur de méthodes et le Query Builder ; résolution multi-passes entre champs frères.</li><li><strong>Variables dynamiques</strong> — Surface Faker complète via <code>{{$faker.module.method}}</code> (ex. <code>{{$faker.person.fullName}}</code>, <code>{{$faker.string.uuid}}</code>), plus alias horloge <code>{{$timestamp}}</code> / <code>{{$isoTimestamp}}</code>.</li><li><strong>Templates helpers</strong> — <code>$pick</code> / <code>$sample</code> / <code>$unique</code> / <code>$repeat</code> / <code>$object</code> / <code>$vector</code> (et <code>$faker.helpers.*</code>) pour listes, objets JSON et tableaux float style embedding ; <code>count:n</code>, <code>count:min,max</code> ou <code>count:&gt;=n</code> / <code>count:&lt;=n</code> pour une longueur dynamique ; <code>$vector | dims:n</code> (option <code>normalize</code>) ; la résolution profonde réhydrate les feuilles structurées exactes.</li><li><strong>Listes nommées</strong> — Définissez des sources <code>$lists.nom</code> figées ou issues d’une dataclass, aux portées globale, profil ou base ; gérez-les depuis le sélecteur <strong>Listes</strong> du pied de page et réutilisez-les dans les templates <code>$pick</code>, <code>$sample</code> et <code>$unique</code>.</li><li><strong>Chips et autocomplétion</strong> — Les variables connues s&#39;affichent en chips ; suggestions pour clés d&#39;environnement, alias, helpers et chemins <code>$faker.*</code> ; les clés non résolues restent visibles en <code>{{…}}</code>.</li><li><strong>Export / Import</strong> — Partagez les environnements en JSON depuis la barre d&#39;outils de l&#39;éditeur.</li><li><strong>API Terminal</strong> — Helpers <code>app.environment</code> et commandes <code>.env</code> / <code>.envs</code>.</li></ul><h4 id="dossiers-de-confiance" tabindex="-1">Dossiers de confiance <a class="header-anchor" href="#dossiers-de-confiance" aria-label="Permalink to &quot;Dossiers de confiance&quot;">​</a></h4><ul><li><strong>Liste d’autorisation</strong> — Sur desktop et mobile, ajoutez des dossiers locaux (Home, Bureau, Documents ou Téléchargements) avec un alias. Les alias restent sur cet appareil et ne font pas partie de l’export de profil.</li><li><strong>Templates $files</strong> — <code>{{$files.photos}}</code> choisit un fichier au hasard, <code>{{$files.photos/cat.jpg}}</code> un chemin précis, et <code>{{$files.photos/**/*.png}}</code> une correspondance glob ; options <code>| ext:</code> et <code>| recursive:false</code>.</li><li><strong>Gestionnaire de fichiers</strong> — Vue liste ou icônes, barre latérale et aperçu redimensionnables, aperçu d’image, et mémorisation de la sélection / des dossiers déployés.</li><li><strong>Copier les templates</strong> — Les actions d’aperçu copient les jetons <code>$files</code> avec une infobulle clic-pour-copier qui devient Copié.</li><li><strong>Confirmation de retrait</strong> — Retirer un dossier de confiance demande une confirmation ; les fichiers sur le disque ne sont pas supprimés.</li><li><strong>Navigation clavier</strong> — Flèches, Début/Fin, Entrée et Retour arrière dans l’explorateur ; ↓ depuis le champ filtre donne le focus à la liste.</li></ul><h4 id="terminal-orda" tabindex="-1">Terminal ORDA <a class="header-anchor" href="#terminal-orda" aria-label="Permalink to &quot;Terminal ORDA&quot;">​</a></h4><ul><li><strong>Dock bas</strong> — Console et Terminal partagent un panneau redimensionnable avec onglets ; l&#39;état ouvert et l&#39;onglet actif sont mémorisés par profil.</li><li><strong>REPL</strong> — Exécutez des expressions <code>ds.*</code> avec coloration Monaco, autocomplétion catalogue (y compris dans <code>query(&quot;…&quot;)</code>) et historique ↑/↓.</li><li><strong>Mode Code</strong> — Éditez des snippets <code>.js</code> nommés ; Entrée = nouvelle ligne, Maj+Entrée (ou Exécuter) lance le code ; <code>⌘/Ctrl+Entrée</code> exécute toujours.</li><li><strong>Pack de snippets</strong> — Export/import gzip (<code>.orda-snippets.gz</code>) ; <code>.load</code> / <code>.run</code> / <code>.rm</code> avec complétion de noms.</li><li><strong>Cellules de résultat</strong> — Entités et sélections s&#39;ouvrent en onglets ; binaires/images via les visionneuses existantes ; le trafic REST apparaît dans Console → Réseau.</li><li><strong>Commandes point</strong> — <code>.help</code>, <code>.exit</code>, etc. ; aide en rendu compact.</li></ul><h4 id="export-rest" tabindex="-1">Export REST <a class="header-anchor" href="#export-rest" aria-label="Permalink to &quot;Export REST&quot;">​</a></h4><ul><li><strong>Onglet Export REST</strong> — Ouvrez-le depuis Outils ou la palette de commandes ; un assistant en quatre étapes (sélection → catégories → variables → aperçu) génère une collection v2.1 ou une spec OpenAPI 3.1 à partir du catalogue.</li><li><strong>Catalogue de requêtes</strong> — Auth, catalog, info, CRUD, entity sets, fonctions dataclass / entity / entitySelection, et singletons. Les méthodes non exposées et le login directory sont désactivés par défaut.</li><li><strong>Aperçu</strong> — Développez ou réduisez les dossiers (y compris tout développer / tout réduire), activez ou non les emojis, Maj+clic pour appliquer ou retirer un emoji par catégorie, et joignez éventuellement la documentation officielle REST 4D à chaque requête.</li><li><strong>Client HTTP et Exécuteur de méthodes</strong> — Exportez aussi la requête courante ou les favoris en collection ou OpenAPI.</li></ul><h4 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h4><ul><li><strong>Apps iOS et Android</strong> — Coques natives avec profils de connexion, HTTP sans CORS et mises en page safe-area.</li><li><strong>Dock tactile</strong> — Console/Terminal en overlay avec cibles plus grandes ; feuille de partage / Téléchargements pour les exports.</li><li><strong>CI mobile</strong> — GitHub Actions construit et publie les artefacts mobile (signature Android incluse).</li></ul><h4 id="executeur-de-methodes" tabindex="-1">Exécuteur de méthodes <a class="header-anchor" href="#executeur-de-methodes" aria-label="Permalink to &quot;Exécuteur de méthodes&quot;">​</a></h4><ul><li><strong>Params et en-têtes Advanced</strong> — Les onglets Params et Headers reprennent l’éditeur souligné du Client HTTP ; le paramètre de requête <code>$method=entityset</code> est prérempli pour les nouveaux appels (l’UI fait foi pour <code>$method</code>).</li><li><strong>Erreurs dans le panneau résultat</strong> — Les erreurs d’exécution, réseau et annulation s’affichent dans le panneau résultat (statut + corps d’erreur), comme dans le Client HTTP ; les messages de validation restent sous la configuration.</li><li><strong>États vides</strong> — Messages « sélectionnez une méthode » clairs dans les volets configuration et résultat tant qu’aucune méthode n’est choisie ; Exécuter reste désactivé (style outline) jusque-là.</li><li><strong>Raccourcis mod-clic</strong> — <code>⌘/Ctrl+clic</code> ouvre un onglet Exécuteur de méthodes en arrière-plan ; <code>⌘/Ctrl+Maj+clic</code> ouvre l’appel dans le Client HTTP (liste, favoris, historique et sélecteur de méthodes).</li></ul><h4 id="console-et-medias" tabindex="-1">Console et médias <a class="header-anchor" href="#console-et-medias" aria-label="Permalink to &quot;Console et médias&quot;">​</a></h4><ul><li><strong>Aperçu d&#39;image réseau</strong> — Prévisualisation inline des réponses image dans le journal réseau.</li><li><strong>Requêtes en cours</strong> — Le corps de la requête est publié dès le démarrage de l’appel ; <strong>Ouvrir dans le Client HTTP</strong> est disponible tant que l’entrée est encore pending.</li><li><strong>Annulation des requêtes</strong> — Interrompez les appels réseau en cours depuis la console lorsque c’est pris en charge.</li><li><strong>Partage / enregistrement</strong> — Partage ou téléchargement des objets binaires et images via les chemins natifs (corrige les échecs de téléchargement WKWebView iOS).</li></ul><h4 id="favoris-et-creation" tabindex="-1">Favoris et création <a class="header-anchor" href="#favoris-et-creation" aria-label="Permalink to &quot;Favoris et création&quot;">​</a></h4><ul><li><strong>Favoris Client HTTP</strong> — Enregistrez, rouvrez et exportez des favoris (y compris export collection / OpenAPI).</li><li><strong>Favoris Exécuteur de méthodes</strong> — Même flux de favoris pour les appels de méthodes.</li><li><strong>Création d&#39;entités par lot</strong> — Créez plusieurs entités avec des champs templated résolus depuis la carte d&#39;environnement active.</li></ul><h4 id="outils-de-selection" tabindex="-1">Outils de sélection <a class="header-anchor" href="#outils-de-selection" aria-label="Permalink to &quot;Outils de sélection&quot;">​</a></h4><ul><li><strong>Points d&#39;entrée</strong> — Menu Outils de sélection sur les listes de dataclass, menus contextuels d&#39;onglets, résultats de sélection de l’Exécuteur, ensembles liés, lignes Home et palette de commandes.</li><li><strong>Analyser</strong> — Valeurs distinctes (<code>$distinct</code>) et cartes de calcul (<code>$compute=$all</code>) pour un attribut de l’ensemble d’entités courant.</li><li><strong>Exporter / Importer</strong> — Formats extensibles (JSON, JSON REST, JSONL, CSV, TSV, SQL, XML, YAML, Markdown, HTML) ; l’import crée ou met à jour des enregistrements dans la dataclass ouverte.</li><li><strong>Anonymiser</strong> — Correspondance de champs avec templates Faker (filtres <code>|</code>), valeurs fixes, conserver ou vider ; retirer des champs du plan pour les omettre des payloads ; graine optionnelle ; aperçu style Client HTTP avec mode auto-détecté.</li><li><strong>Anonymisation d’images</strong> — Les attributs Image modifiables acceptent les templates Faker image tels que <code>{{$faker.image.personPortrait | female}}</code> ; les portraits générés sont récupérés, téléversés via <code>$upload?$rawPict=true</code>, puis remplacés par des IDs 4D avant l’export ou l’écriture.</li><li><strong>Actions d’anonymisation</strong> — Télécharger les données anonymisées, importer comme nouveaux enregistrements, ou écraser les champs mappés de l’ensemble courant (confirmation ; <code>__KEY</code> / <code>__STAMP</code> plus champs modifiés uniquement) ; la progression couvre récupération, génération Faker, téléversements d’images parallèles et finalisation, avec annulation tant que le travail est en cours.</li></ul><h4 id="ux" tabindex="-1">UX <a class="header-anchor" href="#ux" aria-label="Permalink to &quot;UX&quot;">​</a></h4><ul><li><strong>À propos</strong> — Dialogue d&#39;informations depuis le chrome mobile/desktop.</li><li><strong>Hauteurs de panneaux</strong> — Liste d&#39;entités et volets de requête mémorisent la hauteur ; hauteur console bornée si le viewport est inconnu.</li><li><strong>Client HTTP (mobile)</strong> — Résumé requête/réponse adapté aux écrans étroits.</li><li><strong>Envois binaires HTTP</strong> — Les sélecteurs de corps binaire acceptent le glisser-déposer navigateur et desktop, déduisent le <code>Content-Type</code> du fichier sélectionné, et suggèrent les endpoints <code>/rest/$upload?$rawPict=true</code> / <code>$binary=true</code> ; les valeurs Content-Type complètent les types MIME courants.</li><li><strong>Notifications du Client HTTP</strong> — Les réponses contenant <code>__WEBFORM.__NOTIFICATION</code> affichent la même alerte typée et le même stamp de privilège que les résultats de l’Exécuteur de méthodes.</li><li><strong>Décodage d&#39;URL console</strong> — Option pour décoder les URL percent-encoded dans le journal réseau.</li><li><strong>Sélecteur d&#39;environnement</strong> — Contrôle du pied de page affiné pour le profil / la base actifs et l&#39;accès à Gérer.</li><li><strong>Éditeurs de requête partagés</strong> — Le Client HTTP et l’Exécuteur de méthodes partagent l’éditeur clé/valeur Params/Headers pour une édition Advanced cohérente.</li><li><strong>Geste conserver uniquement</strong> — Maj+clic sur une action corbeille dans les correspondances de champs, variables, listes nommées, historique de requêtes, favoris ou lignes clé/valeur conserve cet élément et retire les autres après confirmation.</li></ul><h3 id="documentation-1" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-1" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Pages guide <a href="https://midrissi.github.io/4d-dataexplorer/guide/console.html" target="_blank" rel="noreferrer">Console</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/terminal.html" target="_blank" rel="noreferrer">Terminal ORDA</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/rest-export.html" target="_blank" rel="noreferrer">Export REST</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/environments.html" target="_blank" rel="noreferrer">Variables d&#39;environnement</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/trusted-folders.html" target="_blank" rel="noreferrer">Dossiers de confiance</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/selection-tools.html" target="_blank" rel="noreferrer">Outils de sélection</a> et <a href="https://midrissi.github.io/4d-dataexplorer/guide/mobile.html" target="_blank" rel="noreferrer">Applications mobiles</a>.</li><li>La galerie d&#39;accueil inclut l&#39;éditeur d&#39;environnements et des captures mises à jour (clair / sombre).</li></ul><h3 id="corrections-1" tabindex="-1">Corrections <a class="header-anchor" href="#corrections-1" aria-label="Permalink to &quot;Corrections&quot;">​</a></h3><ul><li><strong>Téléchargements iOS</strong> — Les exports de snippets et de réglages utilisent le chemin natif au lieu de <code>&lt;a download&gt;</code> (NSURLError -3000).</li><li><strong>Restauration de l&#39;onglet</strong> — Recharger avec le Terminal ouvert ne force plus la Console.</li><li><strong>Révélation d&#39;entité</strong> — L&#39;ouverture d&#39;une entité depuis le terminal utilise la clé primaire au lieu d&#39;un <code>$filter</code> sur <code>__KEY</code>.</li><li><strong>Paramètres de requête vides</strong> — L’export collection désactive par défaut les <code>$filter</code> / <code>$orderby</code> / <code>$attributes</code> vides pour qu’ils ne soient pas envoyés tant qu’ils ne sont pas renseignés.</li><li><strong>Réponses OpenAPI</strong> — Les specs exportées listent les statuts REST 4D connus (200, 401, 402, 404, 500).</li><li><strong>Onglet Docs de la collection</strong> — La documentation de chaque requête reprend le markdown officiel 4D REST, pas seulement un résumé.</li><li><strong>Filtres dynamiques</strong> — Genre et bornes numériques / dates sur <code>$faker.*</code> passent par les options Faker.</li><li><strong>Alias Faker <code>userName</code></strong> — Les suggestions et templates acceptent le nom Faker v8 <code>internet.userName</code> comme alias de <code>internet.username</code>.</li><li><strong>Templates docs</strong> — Le guide Environnements et l&#39;accueil affichent les exemples <code>{{…}}</code> sans casser le compilateur Vue de VitePress.</li><li><strong>Résultats obsolètes Exécuteur</strong> — Un échec ou une annulation ne laisse plus un succès précédent sous la configuration ; les erreurs remplacent la vue résultat.</li><li><strong>Corps réseau pending</strong> — Les entrées console n’attendent plus la fin de l’appel pour afficher le corps de requête sortant.</li></ul><h2 id="_1-3-x" tabindex="-1">1.3.x <a class="header-anchor" href="#_1-3-x" aria-label="Permalink to &quot;1.3.x&quot;">​</a></h2><h3 id="apercu-2" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu-2" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h3><p>La version <code>1.3.x</code> introduit Data Explorer Desktop (Tauri + React) avec des profils de connexion persistants, une integration native de la fenetre et des mises a jour automatiques dans l&#39;application ; ajoute un Exécuteur de méthodes pour sélectionner et lancer les méthodes ORDA exposées avec des arguments typés et des vues de résultat spécialisées ; ajoute un Client HTTP pour composer et rejouer des requêtes REST ; ajoute un panneau Console redimensionnable qui journalise les messages applicatifs et chaque requête HTTP ; améliore la gestion des connexions multiplateformes avec la prise en charge de HTTP fetch ; étend la gestion des données binaires avec le chargement différé des BLOB ; optimise le rendu du graphe de structure pour les schémas volumineux ; et affine le retour visuel de l&#39;assistant ainsi que l&#39;accessibilité dans les zones clés de navigation.</p><h3 id="fonctionnalites-2" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites-2" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h3><h4 id="application-desktop" tabindex="-1">Application desktop <a class="header-anchor" href="#application-desktop" aria-label="Permalink to &quot;Application desktop&quot;">​</a></h4><ul><li><strong>Data Explorer Desktop</strong> - Nouvelle application desktop construite avec Tauri et React.</li><li><strong>Connexions enregistrées</strong> - Créez, modifiez et réutilisez des profils de connexion depuis un écran de connexion desktop dédié.</li><li><strong>Fenêtre et thème</strong> - Meilleur comportement au démarrage sur desktop avec synchronisation améliorée de l&#39;état de la fenêtre et du thème.</li><li><strong>Mise a jour automatique</strong> - Détection des mises a jour et gestion du processus dans l&#39;application avec notifications de mise a jour.</li><li><strong>Pipeline de release macOS</strong> - Le workflow GitHub Actions empaquette et téléverse désormais les artefacts desktop macOS.</li></ul><h4 id="executeur-de-methodes-1" tabindex="-1">Exécuteur de méthodes <a class="header-anchor" href="#executeur-de-methodes-1" aria-label="Permalink to &quot;Exécuteur de méthodes&quot;">​</a></h4><ul><li><strong>Onglet Exécuteur de méthodes</strong> - Configurez et exécutez les méthodes 4D exposées depuis un onglet dédié ; ouvrez-le depuis la palette de commandes, les vues classe de données et entité, ou l&#39;assistant.</li><li><strong>Appels selon la portée</strong> - Appelez des méthodes de datastore, classe de données, entité et sélection d&#39;entités avec des expressions de style ORDA (<code>ds.method</code>, <code>ds.Table.method</code>, <code>ds.Table.entity(key).method</code>, <code>ds.Table.sel(key).method</code>).</li><li><strong>Arguments d&#39;exécution</strong> - Construisez des arguments positionnels comme valeurs personnalisées, références d&#39;entité ou sélections d&#39;entités ; réordonnez, dupliquez et validez avant l&#39;exécution.</li><li><strong>Historique des exécutions</strong> - Rouvrez les exécutions réussies récentes ; ⌘/Ctrl+clic sur les clés dans l&#39;historique pour ouvrir l&#39;entité ou la sélection associée.</li><li><strong>Vues de résultat</strong> - Inspectez les résultats JSON, ou ouvrez automatiquement des aperçus spécialisés d&#39;entité et de sélection d&#39;entités.</li></ul><h4 id="panneau-console" tabindex="-1">Panneau Console <a class="header-anchor" href="#panneau-console" aria-label="Permalink to &quot;Panneau Console&quot;">​</a></h4><ul><li><strong>Console ancrée</strong> - Ouvrez un panneau inférieur redimensionnable depuis la barre d&#39;état ou la palette de commandes pour inspecter les journaux pendant la navigation.</li><li><strong>Journalisation réseau</strong> - Chaque requête HTTP est enregistrée avec méthode, URL, statut, durée et taille de réponse ; développez une entrée pour inspecter les en-têtes et les corps (secrets masqués).</li><li><strong>Ouvrir dans le Client HTTP</strong> - Rejouez une entrée réseau capturée dans le Client HTTP avec méthode, URL, en-têtes et corps assainis lorsque disponibles.</li><li><strong>Filtres et contrôles</strong> - Filtrez par niveau (tous, log, info, avertissement, erreur, réseau), réduisez toutes les lignes développées et effacez le tampon en mémoire ; les compteurs d&#39;erreurs et d&#39;avertissements apparaissent sur le bouton Console du pied de page.</li></ul><h4 id="client-http" tabindex="-1">Client HTTP <a class="header-anchor" href="#client-http" aria-label="Permalink to &quot;Client HTTP&quot;">​</a></h4><ul><li><strong>Onglet Client HTTP</strong> - Composez et envoyez des requêtes HTTP depuis Outils ou la palette de commandes, vers le serveur courant ou une origine personnalisée.</li><li><strong>Éditeur de requête</strong> - Autocomplétion méthode / serveur / chemin ; Params, Headers, Body (aucun / formulaire / urlencoded / brut / binaire) et Settings.</li><li><strong>Inspecteur de réponse</strong> - Statut, timing, taille, en-têtes, cookies et corps après Envoyer (⌘/Ctrl+Entrée).</li><li><strong>Options desktop</strong> - Contrôle de session cookies, timeouts, limites de redirection, et option TLS skip sur les builds desktop.</li></ul><h4 id="connectivite-et-chargement-des-donnees" tabindex="-1">Connectivité et chargement des données <a class="header-anchor" href="#connectivite-et-chargement-des-donnees" aria-label="Permalink to &quot;Connectivité et chargement des données&quot;">​</a></h4><ul><li><strong>Prise en charge de HTTP fetch</strong> - Les flux de connexion ont été mis a jour pour prendre en charge les appels HTTP basés sur fetch selon l&#39;environnement.</li><li><strong>Chargement différé des BLOB</strong> - Le chargement des objets binaires est amélioré avec une récupération des BLOB a la demande dans le visualiseur d&#39;entités.</li></ul><h4 id="graphe-de-structure-et-interface" tabindex="-1">Graphe de structure et interface <a class="header-anchor" href="#graphe-de-structure-et-interface" aria-label="Permalink to &quot;Graphe de structure et interface&quot;">​</a></h4><ul><li><strong>Réactivité du graphe</strong> - Le rendu du graphe de classes de données utilise désormais une estimation des dimensions des cartes et des comparaisons optimisées pour le surlignage des nœuds.</li><li><strong>Retour d&#39;activité de l&#39;assistant</strong> - Le chatbot affiche maintenant des états de chargement plus clairs et un indicateur sparkles animé.</li><li><strong>Améliorations d&#39;accessibilité</strong> - Barre latérale, barre d&#39;onglets, palette de commandes et vues associées ont reçu des améliorations d&#39;accessibilité et un raffinement sémantique des classes.</li></ul><h3 id="corrections-2" tabindex="-1">Corrections <a class="header-anchor" href="#corrections-2" aria-label="Permalink to &quot;Corrections&quot;">​</a></h3><ul><li><strong>Rendu des objets binaires</strong> - Amélioration des chemins de gestion binaire différée dans le visualiseur d&#39;entités.</li><li><strong>Stabilité de l&#39;édition des connexions</strong> - Les flux desktop d&#39;édition et de mise a jour de connexion ont été stabilisés.</li><li><strong>Mise en page HTML de couverture</strong> - Ajustement des marges internes dans la sortie HTML de couverture générée pour un rendu plus propre.</li></ul><h2 id="_1-2-x" tabindex="-1">1.2.x <a class="header-anchor" href="#_1-2-x" aria-label="Permalink to &quot;1.2.x&quot;">​</a></h2><h3 id="apercu-3" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu-3" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h3><p>La version <code>1.2.x</code> ajoute un gestionnaire visuel de champs pour les attributs affichés (y compris les chemins de relation imbriqués), le chargement à la demande des entités liées, un panneau de métadonnées regroupées, un visualiseur d&#39;objets binaires, une assistance du langage ORDA dans le générateur de requêtes, un assistant IA avec outils configurables, un générateur de schéma JSON, des éditeurs de code basés sur Monaco, la gestion des ensembles d’entités dans le générateur de requêtes, l’éditeur de métadonnées assistant, des mutations d’entités en lot, l’authentification par clé d’accès, des améliorations du graphe de structure dont l’ajustement à la vue, des états de chargement et d’erreur du visualiseur d’entités et des améliorations de l’interface de l’assistant et du générateur de requêtes.</p><h3 id="fonctionnalites-3" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites-3" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h3><h4 id="champs-affiches" tabindex="-1">Champs affichés <a class="header-anchor" href="#champs-affiches" aria-label="Permalink to &quot;Champs affichés&quot;">​</a></h4><ul><li><strong>Gestionnaire de champs</strong> — Choisissez et réordonnez les attributs affichés dans les colonnes du tableau et les fiches depuis un seul panneau ; la sélection est conservée par onglet.</li><li><strong>Attributs imbriqués</strong> — Explorez les relations pour sélectionner des attributs imbriqués (par ex. <code>company.name</code>, et plus profond) à la fois pour la vue tableau et la vue fiches.</li><li><strong>Sélection par vue</strong> — Conservez des listes d&#39;attributs indépendantes pour la vue tableau et la vue fiches ; glissez pour réordonner.</li><li><strong>Enregistrer par défaut</strong> — Enregistrez la sélection actuelle comme valeur par défaut pour une dataclass, ou rétablissez les valeurs par défaut.</li></ul><h4 id="visualiseur-d-entites" tabindex="-1">Visualiseur d&#39;entités <a class="header-anchor" href="#visualiseur-d-entites" aria-label="Permalink to &quot;Visualiseur d&#39;entités&quot;">​</a></h4><ul><li><strong>Relations différées</strong> — Chargez les entités et sélections d&#39;entités liées à la demande, directement dans les vues formulaire et arborescence.</li><li><strong>Tableau partagé pour les relations</strong> — Les sélections d&#39;entités liées s&#39;affichent dans la même grille de données que la vue tableau.</li><li><strong>Panneau de métadonnées</strong> — Les attributs système de 4D (<code>__KEY</code>, <code>__STAMP</code>, <code>__TIMESTAMP</code>, …) sont regroupés dans un panneau de métadonnées repliable.</li><li><strong>Tous les attributs dans le détail</strong> — La vue détaillée affiche toujours tous les attributs, même lorsque le gestionnaire de champs limite les colonnes ou les champs de la liste.</li><li><strong>Champs de fiche extensibles</strong> — Les fiches affichent un aperçu des premiers champs avec un bouton Afficher plus / Afficher moins.</li><li><strong>Visualiseur d&#39;objets binaires</strong> — Prévisualisez les objets binaires privés de 4D (blobs et images) directement dans le formulaire et le visualiseur d&#39;entités.</li><li><strong>Indicateurs de chargement</strong> — Les données d&#39;entité affichent un état de chargement pendant la récupération, y compris les entités et sélections d&#39;entités liées.</li><li><strong>Récupération après erreur</strong> — Lorsque les entités ne peuvent pas être chargées, un panneau intégré permet de réessayer, de réinitialiser la requête ou de fermer l&#39;onglet.</li><li><strong>Images différées</strong> — Les attributs image se chargent à la demande dans les cellules du tableau et le visualiseur d&#39;entités.</li><li><strong>Info-bulles de cellule</strong> — Survolez les cellules tronquées du tableau pour afficher la valeur complète.</li><li><strong>Tri des colonnes</strong> — Triez les tableaux d&#39;entités par colonne, y compris les tableaux d&#39;entités liées.</li></ul><h4 id="editeur-de-metadonnees-assistant" tabindex="-1">Éditeur de métadonnées assistant <a class="header-anchor" href="#editeur-de-metadonnees-assistant" aria-label="Permalink to &quot;Éditeur de métadonnées assistant&quot;">​</a></h4><ul><li><strong>Onglet Éditeur de métadonnées</strong> — Documentez les classes de données, attributs, méthodes, singletons et méthodes de catalogue pour l’assistant IA ; ouvrir depuis Outils, la palette de commandes ou la barre d’outils de l’assistant.</li><li><strong>Génération de descriptions par IA</strong> — Générez des descriptions champ par champ ou en lot pour toutes les entrées manquantes ; génération optionnelle de schéma JSON pour les paramètres de méthode.</li><li><strong>Indicateurs de descriptions manquantes</strong> — Mettez en évidence les éléments sans documentation ; filtrez la barre latérale pour n’afficher que les entrées manquantes.</li><li><strong>Éditeur JSON</strong> — Modifiez l’objet métadonnées complet directement ; exportez le schéma en fichier JSON.</li></ul><h4 id="assistant-ia" tabindex="-1">Assistant IA <a class="header-anchor" href="#assistant-ia" aria-label="Permalink to &quot;Assistant IA&quot;">​</a></h4><ul><li><strong>Panneau assistant</strong> — Panneau de chat IA avec des outils pour interroger les données, naviguer entre les onglets, exécuter des commandes et contrôler l’interface.</li><li><strong>Outils configurables</strong> — Activez ou désactivez les espaces de noms et les outils individuels de l’assistant dans Paramètres.</li><li><strong>Mode plein écran</strong> — Agrandissez le panneau assistant pour remplir l’écran ; appuyez sur Échap pour quitter.</li><li><strong>Copier la trace</strong> — Copiez la trace d’activité de l’assistant dans le presse-papiers depuis le panneau d’activité.</li><li><strong>Diagrammes Mermaid</strong> — Rendu et gestion d’erreurs améliorés pour les graphiques Mermaid dans les réponses de l’assistant.</li></ul><h4 id="operations-sur-les-donnees" tabindex="-1">Opérations sur les données <a class="header-anchor" href="#operations-sur-les-donnees" aria-label="Permalink to &quot;Opérations sur les données&quot;">​</a></h4><ul><li><strong>Création/mise à jour d’entités en lot</strong> — Créez ou mettez à jour plusieurs entités en un appel via l’API et les outils datastore de l’assistant.</li></ul><h4 id="generateur-de-schema-json" tabindex="-1">Générateur de schéma JSON <a class="header-anchor" href="#generateur-de-schema-json" aria-label="Permalink to &quot;Générateur de schéma JSON&quot;">​</a></h4><ul><li><strong>Onglet Générateur de schéma</strong> — Éditeur visuel pour construire des schémas JSON ; ouvrir depuis le menu Outils dans le pied de page.</li><li><strong>Éditeur d’objets</strong> — Développer ou réduire les objets imbriqués et configurer les attributs du schéma.</li></ul><h4 id="editeur-de-code" tabindex="-1">Éditeur de code <a class="header-anchor" href="#editeur-de-code" aria-label="Permalink to &quot;Éditeur de code&quot;">​</a></h4><ul><li><strong>Éditeur Monaco</strong> — Éditeurs de code et JSON avec complétion de schéma dans toute l’application.</li><li><strong>Préférences de l’éditeur</strong> — Configurez la taille de police, le retour à la ligne et la barre d’outils dans Paramètres ; s’applique aux formulaires d’entités, au générateur de schéma et aux autres éditeurs.</li></ul><h4 id="requetes-et-ensembles-d-entites" tabindex="-1">Requêtes et ensembles d’entités <a class="header-anchor" href="#requetes-et-ensembles-d-entites" aria-label="Permalink to &quot;Requêtes et ensembles d’entités&quot;">​</a></h4><ul><li><strong>Assistance du langage ORDA</strong> — Complétion de code, informations au survol et aide à la signature pour les expressions de requête ORDA, avec résolution des types à partir du catalogue.</li><li><strong>Opérations sur les sélections d&#39;entités</strong> — Combinez des sélections d&#39;entités (<code>AND</code> / <code>OR</code> / <code>EXCEPT</code> / <code>INTERSECT</code>) et libérez des sélections d&#39;entités via l&#39;API et les outils de l&#39;assistant.</li><li><strong>Liaison d’ensemble d’entités</strong> — Liez les onglets de classes de données à des ID d’ensemble d’entités serveur existants ; chargez, copiez et modifiez les ID dans le générateur de requêtes.</li><li><strong>Mise en cache des ensembles</strong> — Les ensembles d’entités côté serveur sont mis en cache et libérés à la fermeture des onglets.</li><li><strong>Paramètres de filtre</strong> — Définissez des paramètres de filtre typés pour les expressions de filtre paramétrées dans le générateur de requêtes.</li></ul><h4 id="profils-et-apparence" tabindex="-1">Profils et apparence <a class="header-anchor" href="#profils-et-apparence" aria-label="Permalink to &quot;Profils et apparence&quot;">​</a></h4><ul><li><strong>Changement rapide de profil</strong> — Changez de profil depuis le pied de page sans ouvrir Paramètres ; l’icône et la couleur du profil sont affichées dans la barre de statut.</li><li><strong>Apparence par profil</strong> — Personnalisez chaque profil avec une icône et une couleur.</li><li><strong>Thème Qodly</strong> — Nouveau thème Qodly en modes clair et sombre (typographie Roboto, accent violet).</li></ul><h4 id="graphe-de-structure" tabindex="-1">Graphe de structure <a class="header-anchor" href="#graphe-de-structure" aria-label="Permalink to &quot;Graphe de structure&quot;">​</a></h4><ul><li><strong>Signatures de méthodes</strong> — Signatures de méthodes mises en évidence dans le graphe de structure.</li><li><strong>Indicateurs d’attributs</strong> — Attributs exposés et poignées de relation visuellement mis en évidence sur les nœuds de classes de données.</li><li><strong>Navigation stable</strong> — Les clics répétés sur une classe de données ne vident plus le graphe ; la fenêtre d’affichage est validée et la sélection des nœuds est conservée.</li><li><strong>Ajuster à la vue</strong> — Recentrez et zoomez le graphe de structure pour afficher tous les nœuds visibles.</li></ul><h4 id="authentification-et-localisation" tabindex="-1">Authentification et localisation <a class="header-anchor" href="#authentification-et-localisation" aria-label="Permalink to &quot;Authentification et localisation&quot;">​</a></h4><ul><li><strong>Connexion par clé d’accès</strong> — Connectez-vous avec une clé d’accès REST lorsque le serveur exige une authentification.</li><li><strong>Internationalisation</strong> — Traductions étendues pour l’interface de l’assistant, le générateur de requêtes et d’autres composants.</li></ul><h3 id="corrections-3" tabindex="-1">Corrections <a class="header-anchor" href="#corrections-3" aria-label="Permalink to &quot;Corrections&quot;">​</a></h3><ul><li><strong>État des onglets</strong> — L&#39;état par onglet reste cohérent lors du changement d&#39;onglet (synchronisation de l&#39;onglet actif) ; l’ID de l’onglet actif est validé avant la fermeture des onglets ou la définition des ID d’ensemble d’entités.</li><li><strong>Raccourcis de profil</strong> — Les raccourcis sont fusionnés avec les valeurs par défaut au chargement des profils, évitant qu’une liste vide n’efface les raccourcis configurés.</li><li><strong>Fenêtre du graphe de structure</strong> — Le panoramique/zoom programmatique ne corrompt plus l’état de la fenêtre enregistré.</li><li><strong>Édition en vue liste</strong> — Édition en ligne désactivée en vue liste pour éviter les modifications accidentelles.</li><li><strong>Ordre d&#39;activation des onglets</strong> — La fermeture d&#39;un onglet active désormais l&#39;onglet le plus récemment utilisé au lieu de l&#39;onglet adjacent.</li></ul><hr><h2 id="_1-1-x" tabindex="-1">1.1.x <a class="header-anchor" href="#_1-1-x" aria-label="Permalink to &quot;1.1.x&quot;">​</a></h2><h3 id="apercu-4" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu-4" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h3><p>La version <code>1.1.x</code> propose un 4D REST Explorer amélioré pour parcourir les classes de données et les entités, avec gestion des profils, barre de recherche globale, modes rapides de la palette de commandes, améliorations des raccourcis clavier, sélection de langue et un ensemble de fonctionnalités centrées sur la consultation et l’édition des données.</p><h3 id="fonctionnalites-4" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites-4" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h3><h4 id="accueil-et-navigation" tabindex="-1">Accueil et navigation <a class="header-anchor" href="#accueil-et-navigation" aria-label="Permalink to &quot;Accueil et navigation&quot;">​</a></h4><ul><li><strong>Écran d’accueil</strong> — Résumé de votre base : statistiques, nombre d’entités et graphiques (<code>bar</code> et <code>pie</code>)</li><li><strong>Barre de recherche globale</strong> — Barre de recherche dans l’en-tête. Cliquez ou donnez le focus pour ouvrir la palette de commandes.</li><li><strong>Palette de commandes</strong> — Ouvrir des entités par ID, ouvrir une classe de données ou rechercher des classes depuis un seul endroit</li><li><strong>Commandes récentes</strong> — Les commandes récemment utilisées apparaissent en haut de la palette avec une icône horloge. L’historique est enregistré par profil.</li><li><strong>Modes rapides</strong> — Depuis la recherche de la palette, taper <code>:</code> pour aller à une entité par index, <code>&gt;</code> pour choisir une classe (vue structure), <code>/</code> pour ouvrir les données d’une classe, ou <code>@</code> pour changer d’onglet.</li><li><strong>Raccourcis clavier</strong> — Raccourcis personnalisés pour les actions courantes (<code>palette de commandes</code>, <code>paramètres</code>, <code>thème</code>, <code>structure</code>, etc.)</li><li><strong>Interface à onglets</strong> — Épingler des onglets, fermer les autres ou les réorganiser par glisser-déposer</li><li><strong>Onglet Notes de version</strong> — Ouvrir les notes de version depuis la barre de statut (pied de page). Le contenu s’affiche dans un onglet dédié</li><li><strong>Langue</strong> — Choisir la langue de l’app (anglais, français, espagnol) depuis la barre de statut (pied de page). Les notes de version et l’interface suivent la langue sélectionnée.</li></ul><h4 id="classe-de-donnees-et-entites" tabindex="-1">Classe de données et entités <a class="header-anchor" href="#classe-de-donnees-et-entites" aria-label="Permalink to &quot;Classe de données et entités&quot;">​</a></h4><ul><li><strong>Navigateur de classes</strong> — Travaillez avec plusieurs classes de données dans des onglets et basculez entre disposition cartes et tableau</li><li><strong>Constructeur de requêtes</strong> — Filtre, tri, sélection de champs et limite. Panneau de requête repliable</li><li><strong>Liste d’entités</strong> — Liste paginée dans un panneau redimensionnable avec badges du nombre d’entités</li><li><strong>Visionneuse d’entité</strong> — Consultez le <code>JSON</code> de l’entité et créez, modifiez ou supprimez des entités (sauf si le mode lecture seule est activé)</li><li><strong>Aller à l’entité</strong> — Ouvrir une entité par ID depuis la palette de commandes</li></ul><h4 id="structure-et-visualisation" tabindex="-1">Structure et visualisation <a class="header-anchor" href="#structure-et-visualisation" aria-label="Permalink to &quot;Structure et visualisation&quot;">​</a></h4><ul><li><strong>Graphe de structure</strong> — Diagramme des classes de données et de leurs liens. Mettre en surbrillance une classe depuis le menu contextuel de l’onglet</li><li><strong>Apparence des classes</strong> — Couleurs et icônes par classe dans Paramètres</li></ul><h4 id="profils-et-parametres" tabindex="-1">Profils et paramètres <a class="header-anchor" href="#profils-et-parametres" aria-label="Permalink to &quot;Profils et paramètres&quot;">​</a></h4><ul><li><strong>Gestion des profils</strong> — Créez, renommez, dupliquez et supprimez des profils dans Paramètres. Chaque profil a son propre thème, raccourcis, largeur de la barre latérale et autres préférences.</li><li><strong>Import / export</strong> — Exportez tous les paramètres ou des profils sélectionnés vers un fichier JSON, et importez des paramètres ou profils depuis un fichier (avec la possibilité de choisir quels profils importer).</li></ul><h4 id="parametres-et-apparence" tabindex="-1">Paramètres et apparence <a class="header-anchor" href="#parametres-et-apparence" aria-label="Permalink to &quot;Paramètres et apparence&quot;">​</a></h4><ul><li><strong>Apparence</strong> — Plusieurs thèmes de couleurs (<code>Slate</code>, <code>Tangerine</code>, <code>Violet Bloom</code>, <code>Graphite</code>, <code>Aurora</code>, etc.)</li><li><strong>Mode clair / sombre</strong> — Suivre le système ou basculer manuellement</li><li><strong>Vues par défaut</strong> — Choisir la disposition par défaut (<code>cartes</code> ou <code>tableau</code>) et la taille de page pour les nouveaux onglets de classe</li><li><strong>Raccourcis clavier</strong> — Activer ou désactiver les raccourcis et consulter la liste complète dans Paramètres</li><li><strong>Apparence des classes</strong> — Définir couleurs et icônes pour chaque classe dans la barre latérale et les onglets</li></ul><h4 id="raccourcis-clavier" tabindex="-1">Raccourcis clavier <a class="header-anchor" href="#raccourcis-clavier" aria-label="Permalink to &quot;Raccourcis clavier&quot;">​</a></h4><ul><li><strong>Fenêtre des raccourcis</strong> — La section « Affichage » est maintenant affichée en deux colonnes pour une disposition plus compacte.</li><li><strong>Enregistrer en accord</strong> — L’option « Enregistrer en accord (séquence de deux touches) » est maintenant dans la fenêtre d’enregistrement de raccourci, pour choisir le mode accord lors de l’enregistrement.</li><li><strong>Affichage des raccourcis</strong> — Les boutons de raccourci dans Paramètres utilisent un style plus léger, avec bordure uniquement (sans fond) pour les touches.</li></ul><h4 id="securite-et-modes" tabindex="-1">Sécurité et modes <a class="header-anchor" href="#securite-et-modes" aria-label="Permalink to &quot;Sécurité et modes&quot;">​</a></h4><ul><li><strong>Mode lecture seule</strong> — Interrupteur dans l’en-tête pour désactiver création/édition/suppression pour une navigation sûre</li><li><strong>Mode édition</strong> — Créer, modifier et supprimer des entités lorsqu’il est activé</li></ul><h3 id="technique" tabindex="-1">Technique <a class="header-anchor" href="#technique" aria-label="Permalink to &quot;Technique&quot;">​</a></h3><ul><li><strong>API REST 4D</strong> — Communication avec votre serveur 4D en REST et prise en charge des paramètres de requête standard</li><li><strong>État persistant</strong> — Onglets, largeur de la barre latérale et paramètres stockés par base (<code>BASEID</code>)</li></ul>',123)])])}const m=t(n,[["render",a]]);export{g as __pageData,m as default};
